const poolNames = {
  0: "3 tháng (15% APR)",
  1: "6 tháng (25% APR)", 
  2: "12 tháng (40% APR)"
};

const Staking = () => {
  const { address: account } = useAccount();
  const config = useConfig();
  const [stakeAmount, setStakeAmount] = useState('');
  const [loading, setLoading] = useState(false);
  const [selectedPoolId, setSelectedPoolId] = useState(0);
  const [userStakes, setUserStakes] = useState([]);
  const [showSuccessModal, setShowSuccessModal] = useState(false);

  // Read user stakes
  const { data: userStakesData, refetch: refetchStakes } = useReadContract({
    abi: stakingContractAbi,
    address: stakingContractAddress,
    functionName: 'getUserStakes',
    args: [account],
    query: {
      enabled: !!account,
    },
  });

  // Read token balance
  const { data: tokenBalance } = useReadContract({
    abi: tokenContractAbi,
    address: tokenContractAddress,
    functionName: 'balanceOf',
    args: [account],
    query: {
      enabled: !!account,
    },
  });

  // Read allowance
  const { data: allowanceData, refetch: refetchAllowance } = useReadContract({
    abi: tokenContractAbi,
    address: tokenContractAddress,
    functionName: 'allowance',
    args: [account, stakingContractAddress],
    query: {
      enabled: !!account,
    },
  });

  // Read staking fee
  const { data: stakingFee } = useReadContract({
    abi: stakingContractAbi,
    address: stakingContractAddress,
    functionName: 'STAKING_FEE',
  });

  // Read unstaking fee
  const { data: unstakingFee } = useReadContract({
    abi: stakingContractAbi,
    address: stakingContractAddress,
    functionName: 'UNSTAKING_FEE',
  });

  useEffect(() => {
    if (userStakesData) {
      setUserStakes(userStakesData);
    }
  }, [userStakesData]);

  const handleStake = async () => {
    if (!account) {
      toast.error('Connect Your Wallet');
      return;
    }

    if (!stakeAmount || parseFloat(stakeAmount) <= 0) {
      toast.error('Input Valid BNB');
      return;
    }

    if (!tokenBalance || parseEther(stakeAmount) > tokenBalance) {
      toast.error('Insufficient Funds');
      return;
    }

    setLoading(true);
    try {
      const amountToStake = parseEther(stakeAmount);
      const feeAmount = stakingFee || parseEther('0.005');

      // Check and approve token if needed
      if (!allowanceData || allowanceData < amountToStake) {
        toast.info('Transfer Token...');
        const txApprove = await writeContract(config, {
          abi: tokenContractAbi,
          address: tokenContractAddress,
          functionName: 'approve',
          args: [stakingContractAddress, amountToStake]
        });
        await waitForTransactionReceipt(config, { hash: txApprove });
        toast.success('Transfer Token Approved');
        
        // Refetch allowance
        await refetchAllowance();
      }

      toast.info('Loading stake...');
      const txStake = await writeContract(config, {
        abi: stakingContractAbi,
        address: stakingContractAddress,
        functionName: 'createStake',
        args: [amountToStake, selectedPoolId],
        value: feeAmount
      });

      toast.info('Wait for confirm tx...');
      const receipt = await waitForTransactionReceipt(config, { 
        hash: txStake 
      });

      // Call backend API
      try {
        await axios.post('https://pi-ai-backend-starter.onrender.com/stake', {
          wallet: account,
          amount: parseFloat(stakeAmount),
          poolId: selectedPoolId,
          txHash: txStake
        });
      } catch (apiError) {
        console.warn('Backend API call failed:', apiError);
      }

      toast.success('Stake Successful!');
      setStakeAmount('');
      setShowSuccessModal(true);
      // Refetch user stakes
      await refetchStakes();
    } catch (err) {
      console.error('Stake error:', err);
      if (err.message.includes('user rejected') || err.message.includes('User rejected')) {
        toast.error('transaction cancled');
      } else if (err.message.includes('insufficient funds')) {
        toast.error('Insufficient gas fee');
      } else {
        toast.error('Stake Failed: ' + (err.shortMessage || err.message));
      }
    } finally {
      setLoading(false);
    }
  };

  const handleUnstake = async (stakeIndex) => {
    if (!account) {
      toast.error('Connect your wallet');
      return;
    }

    setLoading(true);
    try {
      const feeAmount = unstakingFee || parseEther('0.005');
      
      toast.info('Loading unstake...');
      const txUnstake = await writeContract(config, {
        abi: stakingContractAbi,
        address: stakingContractAddress,
        functionName: 'unstake',
        args: [stakeIndex],
        value: feeAmount
      });

      toast.info('Wait for transaction confirm...');
      const receipt = await waitForTransactionReceipt(config, { 
        hash: txUnstake 
      });

      toast.success('Unstake successful!');
      
      // Refetch user stakes
      await refetchStakes();
    } catch (err) {
      console.error('Unstake error:', err);
      if (err.message.includes('user rejected') || err.message.includes('User rejected')) {
        toast.error('Transaction cancled');
      } else {
        toast.error('Unstake Failed: ' + (err.shortMessage || err.message));
      }
    } finally {
      setLoading(false);
    }
  };

  const calculateTotalStaked = () => {
    if (!userStakes || userStakes.length === 0) return '0';
    return userStakes
      .filter(stake => !stake.claimed)
      .reduce((total, stake) => total + Number(formatEther(stake.amount)), 0)
      .toFixed(2);
  };

  return ( <>
    <StakingContainer>
      <Title>Staking</Title>

      <StatsContainer>
        <StatCard>
          <StatValue>{calculateTotalStaked()}</StatValue>
          <StatLabel>Total Staked (PAI)</StatLabel>
        </StatCard>
        <StatCard>
          <StatValue>{tokenBalance ? formatEther(tokenBalance) : '0'}</StatValue>
          <StatLabel>Available Balance (PAI)</StatLabel>
        </StatCard>
        <StatCard>
          <StatValue>{userStakes ? userStakes.length : '0'}</StatValue>
          <StatLabel>Active Stakes</StatLabel>
        </StatCard>
      </StatsContainer>

      <StakingForm>
        <InputGroup>
          <Label>Amount to Stake</Label>
          <Input
            type="number"
            value={stakeAmount}
            onChange={(e) => setStakeAmount(e.target.value)}
            placeholder="Enter amount to stake"
            min="0"
            step="0.01"
          />
        </InputGroup>

        <Label>Staking Pool</Label>
        <Select
          value={selectedPoolId}
          onChange={(e) => setSelectedPoolId(Number(e.target.value))}
        >
          <option value={0}>3 months (15% APR)</option>
          <option value={1}>6 months (25% APR)</option>
          <option value={2}>12 months (40% APR)</option>
        </Select>

        {stakingFee && (
          <div style={{ fontSize: '0.9rem', color: '#888', marginBottom: '1rem' }}>
            Platform fee: {formatEther(stakingFee)} BNB
          </div>
        )}

          <Button
            primary
            onClick={handleStake}
            disabled={loading || !stakeAmount || !account}
          >
          {loading ? 'Processing...' : 'Stake Tokens'}
          </Button>
      </StakingForm>

      {userStakes && userStakes.length > 0 && (
        <div>
          <Title style={{ fontSize: '1.5rem', marginBottom: '1rem' }}>Your Stakes</Title>
          {userStakes.map((stake, index) => (
            <StakeCard key={index}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <div>
                  <div style={{ color: '#4ECDC4', fontSize: '1.2rem', marginBottom: '0.5rem' }}>
                    {formatEther(stake.amount)} PAI
                  </div>
                  <div style={{ color: '#888', fontSize: '0.9rem' }}>
                    Pool: {poolNames[stake.poolId]}
                  </div>
                  <div style={{ color: '#888', fontSize: '0.9rem' }}>
                    Staked: {new Date(Number(stake.startTime) * 1000).toLocaleDateString()}
                  </div>
                  <div style={{ color: stake.claimed ? '#888' : '#4ECDC4', fontSize: '0.9rem' }}>
                    Status: {stake.claimed ? 'Claimed' : 'Active'}
                  </div>
                </div>
                {!stake.claimed && (
      <Button
                    onClick={() => handleUnstake(index)}
                    disabled={loading}
                    style={{ minWidth: '100px' }}
                  >
                    {loading ? 'Processing...' : 'Unstake'}
      </Button>
                )}
              </div>
            </StakeCard>
          ))}
        </div>
      )}
    </StakingContainer>
    {showSuccessModal && (
        <SuccessModal>
          <ModalContent>
            <SuccessIcon>✅</SuccessIcon>
            <ModalTitle>Stake Token Successfull !</ModalTitle>
            <ModalText>
              You're staked {stakeAmount} $PAI tokens.
              <br />
              Transaction Confirmed on blockchain.
            </ModalText>
            <CloseButton onClick={() => setShowSuccessModal(false)}>
              Close
            </CloseButton>
          </ModalContent>
        </SuccessModal>
      )}
    </>
  );
};

export default Staking; 