const Referral = () => {
  const { address: account } = useAccount();
  const [referralLink, setReferralLink] = useState('');
  const [referralsList, setReferralsList] = useState([]);
  const [referralCount, setReferralCount] = useState(0);
  const [totalRewards, setTotalRewards] = useState('0');
  const [loading, setLoading] = useState(false);
  const [referralStats, setReferralStats] = useState({
    totalReferrals: 0,
    totalEarnings: '0',
    pendingRewards: '0',
    referralCode: ''
  });

  // Fetch referral stats
  const { data: referralStatsData } = useReadContract({
    abi: idoContractAbi,
    address: idoContractAddress,
    functionName: 'getReferralStats',
    args: [account],
    query: {
      enabled: !!account,
    },
  });
      
  useEffect(() => {
    if (referralStatsData !== undefined) {
		setReferralCount(referralStatsData.totalRefs ? Number(referralStatsData.totalRefs) : 0);

      setTotalRewards(
		referralStatsData.pendingRewards ? formatEther(referralStatsData.pendingRewards) : '0'
	  );
	  
    }
  }, [referralStatsData]);
  useEffect(() => {
	const fetchReferralList = async () => {
	  if (!account) return;
	  try {
		const res = await axios.get(`https://pi-ai-backend-starter.onrender.com/referral/list/${account}`);
		setReferralsList(res.data || []);
	  } catch (err) {
		console.error('Errors fetch referral list:', err);
	  }
	};
  
	fetchReferralList();
  }, [account]);
  
  useEffect(() => {
    if (account) {
      const baseUrl = window.location.origin;
      setReferralLink(`${baseUrl}/?ref=${account}`);
    }
  }, [account]);

  const handleCopyLink = () => {
    navigator.clipboard.writeText(referralLink);
    toast.success('Referral link copied to clipboard!');
  };

  const fetchReferralStats = async () => {
    if (!account) return;

    try {
      const response = await axios.get(`https://pi-ai-backend-starter.onrender.com/referral/stats/${account}`);
      const data = response.data;
      
      setReferralStats({
        totalReferrals: data.totalReferrals || 0,
        totalEarnings: data.totalEarnings ? formatEther(data.totalEarnings) : '0',
        pendingRewards: data.pendingRewards ? formatEther(data.pendingRewards) : '0',
        referralCode: data.referralCode || ''
      });
    } catch (error) {
      console.error('Error fetching referral stats:', error);
      toast.error('Error fetching ref information');
    }
  };

  const handleClaimRewards = async () => {
    if (!account) {
      toast.error('Connect Wallet');
      return;
    }

    try {
      setLoading(true);

      const tx = await writeContract({
        abi: idoContractAbi,
        address: idoContractAddress,
        functionName: 'claimReferralRewards',
      });

      await waitForTransactionReceipt({ hash: tx.hash });

      await axios.post('https://pi-ai-backend-starter.onrender.com/referral/claim', {
        wallet: account,
        txHash: tx.hash
      });

      toast.success('Claim reward successfull !');
      fetchReferralStats();
    } catch (error) {
      console.error('Error claiming rewards:', error);
      toast.error('Claim reward failed');
    } finally {
      setLoading(false);
    }
  };

  

  return (
    <ReferralContainer>
      <Title>Referral Program</Title>
      
      <ReferralLink>
        <LinkText>{referralLink}</LinkText>
        <CopyButton onClick={handleCopyLink}>Copy</CopyButton>
      </ReferralLink>

      <StatsContainer>
        <StatBox>
          <StatLabel>TOTAL REFERRALS </StatLabel>
          <StatValue>{referralCount}</StatValue>
        </StatBox>
        
      </StatsContainer>

      <StatsContainer>
        
        
        <StatBox>
          <StatLabel>Total Earnings</StatLabel>
          <StatValue>{referralStats.totalEarnings} BNB</StatValue>
        </StatBox>
        
        <StatBox>
          <StatLabel>Pending Rewards</StatLabel>
          <StatValue>{referralStats.pendingRewards} BNB</StatValue>
        </StatBox>
      </StatsContainer>

      <ReferralCode>
        <Label>Your Referral Code</Label>
        <CodeBox>{referralStats.referralCode || 'Loading...'}</CodeBox>
      </ReferralCode>

      <ClaimButton
        onClick={handleClaimRewards}
        disabled={loading || parseFloat(referralStats.pendingRewards) <= 0}
      >
        {loading ? 'Processing...' : 'Claim Rewards'}
      </ClaimButton>
	  <Title style={{ marginTop: '2rem' }}>List Referrals </Title>
{referralsList.length === 0 ? (
  <p style={{ color: '#ccc' }}>Nobody Invited </p>
) : (
  <table style={{ width: '100%', color: 'white', marginTop: '1rem' }}>
    <thead>
      <tr>
        <th style={{ textAlign: 'left' }}>Wallet address </th>
        <th>Token Bought </th>
        <th>Time </th>
      </tr>
    </thead>
    <tbody>
      {referralsList.map((item, index) => (
        <tr key={index}>
          <td>{item.wallet}</td>
          <td>{parseFloat(item.tokensReceived).toLocaleString()} PAI</td>
          <td>{new Date(item.timestamp).toLocaleString()}</td>
        </tr>
      ))}
    </tbody>
  </table>
)}

    </ReferralContainer>
  );
};

export default Referral; 