// src/AppKitProvider.jsx
import { createAppKit } from '@reown/appkit/react';
import { WagmiProvider } from 'wagmi';
import { mainnet, bscTestnet } from '@reown/appkit/networks';
import { WagmiAdapter } from '@reown/appkit-adapter-wagmi';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';

const queryClient = new QueryClient();
const projectId = '92ff03c6421c747aa1db90fb8a1c1268'; // từ https://cloud.reown.com
const metadata = {
  name: 'P-AI DApp',
  description: 'P-AI Token DApp',
  url: 'https://dat-52.github.io/P-AI/',
  icons: ['https://dat-52.github.io/P-AI/logo192.png'],
};
const networks = [mainnet, bscTestnet];

const wagmiAdapter = new WagmiAdapter({ networks, projectId, ssr: true });

createAppKit({
  adapters: [wagmiAdapter],
  networks,
  projectId,
  metadata,
  features: { analytics: true },
});

export function AppKitProvider({ children }) {
  return (
    <WagmiProvider config={wagmiAdapter.wagmiConfig}>
      <QueryClientProvider client={queryClient}>
        {children}
      </QueryClientProvider>
    </WagmiProvider>
  );
}
