const IDO = ({ account }) => {
  const config = useConfig();
  const [bnbAmount, setBnbAmount] = useState('');
  const [tokenAmount, setTokenAmount] = useState('0');
  const [loading, setLoading] = useState(false);
  const [refAddress, setRefAddress] = useState(null);
  const [showSuccessModal, setShowSuccessModal] = useState(false);
  const [tokenPurchased, setTokenPurchased] = useState('0');
  
  

  
  const { data: fixedFee } = useReadContract({
    abi: idoContractAbi,
    address: idoContractAddress,
    functionName: 'FIXED_FEE',
  });
  const { data: tokensPerBnb } = useReadContract({
    abi: idoContractAbi,
    address: idoContractAddress,
    functionName: 'TOKENS_PER_BNB',
  });
  const handleBnbChange = (e) => {
	const value = e.target.value;
	setBnbAmount(value);
  
	if (value && tokensPerBnb) {
	  try {
		const bnbInWei = parseUnits(value, 18); // 0.001 BNB => 1000000000000000n
  
		// token = (bnbWei * tokensPerBnb) / 1e18
		const tokensRaw = (bnbInWei * tokensPerBnb) / BigInt("1000000000000000000");
  
		// Vì token PAI có 18 decimals, hiển thị nguyên số token
		const formattedTokens = formatUnits(tokensRaw, 18); // 👈
  
		setTokenAmount(formattedTokens);
	  } catch (err) {
		console.error('BNB nhập không hợp lệ:', err);
		setTokenAmount('0');
	  }
	} else {
	  setTokenAmount('0');
	}
  };
  

  const handleBuy = async () => {
    if (!account) {
      toast.error('Please Connect Your Wallet');
      return;
    }

    if (!bnbAmount || parseFloat(bnbAmount) <= 0) {
      toast.error('Invalid BNB Input');
      return;
    }

    try {
      setLoading(true);
      const bnbValue = parseEther(bnbAmount);
      const feeAmount = fixedFee || parseEther('0.008'); // Use contract fee or fallback
      const totalValue = bnbValue + feeAmount;
      
      // Validate refAddress before using it
      const validRefAddress = refAddress && isAddress(refAddress) ? refAddress : zeroAddress;
      
      toast.info('Transaction Loading...');
      
      const txHash = await writeContract(config, {
        abi: idoContractAbi,
        address: idoContractAddress,
        functionName: 'buyTokens',
        args: [validRefAddress],
        value: totalValue,
      });

      toast.info('Wait for confirm TX...');
      const receipt = await waitForTransactionReceipt(config, { 
        hash: txHash 
      });

      // Call backend API
      try {
        await axios.post('https://pi-ai-backend-starter.onrender.com/ido/purchase', {
          wallet: account,
          bnbPaid: parseFloat(bnbAmount),
          tokensReceived: parseFloat(tokenAmount),
          referrer: validRefAddress !== zeroAddress ? validRefAddress : null,
          txHash: txHash
        });
      } catch (apiError) {
        console.warn('Backend API call failed:', apiError);
        // Continue even if backend fails
      }
      
      toast.success('Buy token successful!');
	  setTokenPurchased(tokenAmount);
      setBnbAmount('');
      setTokenAmount('0');
      setShowSuccessModal(true);
    } catch (err) {
      console.error('Buy error:', err);
      if (err.message.includes('user rejected') || err.message.includes('User rejected')) {
        toast.error('Transaction cancled');
      } else if (err.message.includes('insufficient funds')) {
        toast.error('insufficient BNB');
      } else if (err.message.includes('InvalidAddressError')) {
        toast.error('Address referral Invalid');
      } else {
        toast.error('Buy token failed: ' + (err.shortMessage || err.message));
      }
    } finally {
      setLoading(false);
    }
  };
  
  

useEffect(() => {
  const params = new URLSearchParams(window.location.search);
  const ref = params.get('ref');
  if (ref) setRefAddress(ref);
}, []);


  return (
    <>
      <IDOContainer>
        <Title>Buy $PAI Tokens</Title>
        <InputGroup>
          <Label>Amount in BNB</Label>
          <Input
            type="number"
            value={bnbAmount}
            onChange={handleBnbChange}
            placeholder="Enter BNB amount"
            min="0"
            step="0.01"
          />
        </InputGroup>

        <TokenInfo>
          <Label>You will receive:</Label>
          <div>{tokenAmount} $PAI tokens</div>
        </TokenInfo>

        <BuyButton
          onClick={handleBuy}
          disabled={loading || !bnbAmount || !account}
        >
          {loading ? 'Processing...' : 'Buy Tokens'}
        </BuyButton>
      </IDOContainer>

      {showSuccessModal && (
        <SuccessModal>
          <ModalContent>
            <SuccessIcon>✅</SuccessIcon>
            <ModalTitle>Buy Token Successfull !</ModalTitle>
            <ModalText>
              You're bought {tokenPurchased} $PAI tokens.
              <br />
              Transaction Confirmed on blockchain.
            </ModalText>
            <CloseButton onClick={() => setShowSuccessModal(false)}>
              Close
            </CloseButton>
          </ModalContent>
        </SuccessModal>
      )}
    </>
  );
};

